from pathlib import Path
import json,os,numpy as np,torch
R=Path(os.environ['LAYER_RUN']);C=R/'confirmation';rows=json.loads((C/'sample-manifest.json').read_text());d=np.load(C/'vectors.npz');p=np.load(C/'predictions.npz');m=torch.load(R/'readout/mlp/models.pt',map_location='cpu',weights_only=False);task=np.array([r['task'] for r in rows]);ref=d['reference'];condition=d['condition'];ii=np.flatnonzero((task[ref]=='place_object_basket')&(condition=='noise0.10'));rr=ref[ii];cc=np.flatnonzero((task[ref]=='place_object_basket')&(condition=='clean'));mapping={v:i for i,v in enumerate(ref[cc])};clean=p['mlp/place_object_basket/L12_pca/clean'][[mapping[i] for i in rr]];noisy=p['mlp/place_object_basket/L12_pca/noise0.10'];truth=d['target'][rr];scale=m['scales']['place_object_basket/L12_pca'][3].numpy();result={}
for typ in [np.float32,np.float64]:
 a,b,y,s=[v.astype(typ) for v in [noisy,clean,truth,scale]];e=(b-y)/s;q=(a-b)/s;lhs=q*q+2*e*q;rhs=((a-y)/s)**2-e*e;result[typ.__name__]={'max_abs_identity_residual':float(np.max(np.abs(lhs-rhs))),'original_tolerance_pass':bool(np.allclose(lhs,rhs,rtol=3e-5,atol=3e-6)),'strict_float64_tolerance_pass':bool(np.allclose(lhs,rhs,rtol=1e-10,atol=1e-12))}
result.update(scope='Same saved predictions, labels and scales; only subtraction arithmetic precision changes',original_secondary_exit_code=1,primary_results_unchanged=True);(C/'decomposition-precision-diagnostic.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
